// Add the items to the catalog, and the two new slots to the locker.
GI_ITEMS.forEach(i => { ITEMS.push(i); ITEM[i.id] = i; });
SLOTS.gear = 'Gear'; SLOTS.back = 'Back items';
// The icon drawn in its rarity color with a thick dark outline, like a game item.
const giBody = it => `<g style="color:var(${RARITY[it.r].c})" stroke="#1b1d22" stroke-width="22" stroke-linejoin="round" paint-order="stroke">${GI[it.id]}</g>`;
const giIcon = it => `<svg viewBox="-16 -16 544 544" class="vec gi" role="img" aria-label="${esc(it.name)}">${giBody(it)}</svg>`;
// Nested inside the character drawing at x, y with size w x h.
const giNest = (id, x, y, w, hh) => `<svg x="${x}" y="${y}" width="${w}" height="${hh}" viewBox="-16 -16 544 544">${giBody(ITEM[id])}</svg>`;
